// MC-445: Poll GitHub for merged PRs, transition linked issues from approved → released
const GH_TOKEN = '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';
const MC_API = 'http://localhost:3000/api/issues';
const DEPLOY_CHANNEL = '1487584904135970816'; // #deployments
const REPOS = ['nabitllc/kaos-mission-control', 'nabitllc/vespera'];

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedPRs) staticData.processedPRs = {};

const now = Date.now();
// Prune entries older than 30 days
for (const [key, ts] of Object.entries(staticData.processedPRs)) {
  if (now - ts > 30 * 24 * 60 * 60 * 1000) delete staticData.processedPRs[key];
}

const ghHeaders = {
  'Authorization': 'Bearer ' + GH_TOKEN,
  'Accept': 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'KAOS-n8n-agent'
};

const transitions = [];
const errors = [];

for (const repo of REPOS) {
  // Get recently merged PRs (last 20)
  let prs;
  try {
    prs = await helpers.httpRequest({
      method: 'GET',
      url: 'https://api.github.com/repos/' + repo + '/pulls?state=closed&per_page=20&sort=updated&direction=desc',
      headers: ghHeaders
    });
  } catch(e) {
    errors.push({ repo, error: String(e) });
    continue;
  }

  // Filter only merged PRs
  const mergedPRs = prs.filter(pr => pr.merged_at);

  for (const pr of mergedPRs) {
    const prKey = repo + '#' + pr.number;
    if (staticData.processedPRs[prKey]) continue;
    staticData.processedPRs[prKey] = now;

    const prUrl = pr.html_url;

    // Find MC issue with matching pr_url
    let issues;
    try {
      const allIssues = await helpers.httpRequest({
        method: 'GET',
        url: MC_API,
        headers: { 'Content-Type': 'application/json' }
      });
      issues = allIssues.filter(i => i.pr_url && i.pr_url.toLowerCase() === prUrl.toLowerCase());
    } catch(e) {
      errors.push({ prKey, error: 'MC API fetch failed: ' + String(e) });
      continue;
    }

    if (!issues.length) {
      // No issue linked — skip silently
      continue;
    }

    for (const issue of issues) {
      if (issue.status !== 'approved') {
        // Already transitioned or not in approved state
        continue;
      }

      // Transition approved → released
      try {
        const result = await helpers.httpRequest({
          method: 'PATCH',
          url: MC_API,
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            id: issue.id,
            status: 'released',
            transitioned_by: 'ops',
            implementation_notes: 'Auto-released by MC-445 n8n workflow. PR merged: ' + prUrl
          })
        });

        transitions.push({
          task_key: issue.task_key,
          title: issue.title,
          pr_url: prUrl,
          repo
        });

        // Discord notification via n8n HTTP (no child_process needed)
        // Non-critical: wrapped in try/catch
        try {
          const repoShort = repo.split('/')[1];
          const msg = '🚀 **Released: ' + issue.task_key + '** — ' + issue.title.slice(0, 80) + '\n' +
            '• **Repo:** ' + repoShort + '\n' +
            '• **PR:** <' + prUrl + '>\n' +
            '• **Status:** approved → released\n' +
            '• **Merged at:** ' + pr.merged_at;
          await helpers.httpRequest({
            method: 'POST',
            url: 'http://localhost:3000/api/notify',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ channel: 'discord', target: 'channel:' + DEPLOY_CHANNEL, message: msg })
          });
        } catch(e) {
          // Discord post failed, non-critical
        }
      } catch(e) {
        errors.push({ task_key: issue.task_key, error: 'PATCH failed: ' + String(e) });
      }
    }
  }
}

return [{ json: {
  transitions_count: transitions.length,
  transitions,
  errors,
  timestamp: new Date().toISOString()
} }];
